sp_widget.client_script:
api.controller=function($scope) {
  /* widget controller */
  var c = this;

	// Estado inicial (pode ser null, true ou false)
$scope.isLowercase = null;

// Escuta evento do rootScope para atualizar o estado
$scope.$root.$on('toggleCaseEvent', function(event, isLowercase) {
  $scope.isLowercase = isLowercase;
});

};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Roboto:wght@500&family=Roboto+Flex:opsz,wght@8..144,100..1000&display=swap');

  /* Container que deixa o link centralizado vertical e horizontalmente */
  .centered-link-container {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 14vh; /* ocupa a altura total da viewport */
    /* background-color: #f9f9f9; /* opcional, para destacar */ */
    margin-bottom: 4rem;
    margin-top: 4rem;
  }

  /* Estilo do link arredondado */
  .rounded-link {
    /* ESTILOS DE TEXTO SOLICITADOS */
    font-family: 'Roboto', sans-serif; /* Ajustado para Roboto simples */
    font-weight: 500; /* Peso Medium */
    font-size: 20px; /* Tamanho 20px */
    line-height: 1.0; /* 100% de line-height */
    letter-spacing: 0; /* 0% de letter-spacing */
    text-align: center; /* Alinhamento centralizado */

    /* Estilo do Botão Fantasma (Cor e Borda) */
    color: #4671C4; /* COR NORMAL: Texto azul */
    background: white; /* Fundo branco */
    border: 3px solid #4671C4; /* Borda azul */
    padding: 10px 30px;
    border-radius: 50px; /* bastante arredondado */
    text-decoration: none;
    box-shadow: 0 4px 8px rgba(0,0,0,0.2);
    /* Transição suave para cores e box-shadow */
    transition: background-color 0.3s ease, box-shadow 0.3s ease, color 0.3s ease; 
    /* Garante que o ícone e o texto fiquem alinhados */
    display: inline-flex; 
    align-items: center; 
  }

  /* Estilo do hover (inverte as cores) */
  .rounded-link:hover {
    background-color: #4671C4; /* HOVER: Fundo azul */
    color: white; /* HOVER: Texto branco */
    box-shadow: 0 6px 12px rgba(0,0,0,0.3);
    cursor: pointer;
    text-decoration: none;
  }

  /* Estilo do ícone */
  .icon-spacing {
    margin-left: 15px; /* Espaço entre o texto e a seta */
    font-size: 20px; /* Alinhando o tamanho do ícone com o font-size do link (20px) */
    transition: transform 0.3s ease; 
  }

  /* Efeito de movimento no ícone quando o mouse passa sobre o link */
  .rounded-link:hover .icon-spacing {
    transform: translateX(5px);
  }

  /* Estilos para manipulação de texto (Angular/ng-class) */
  .lowercase-text {
    text-transform: lowercase;
  }

  .uppercase-text {
    text-transform: uppercase;
  }

  /* Responsivo para telas pequenas */
  @media (max-width: 600px) {
    .rounded-link {
      font-size: 18px; /* Ajuste o tamanho da fonte para mobile (de 20px para 18px) */
      padding: 15px 40px;
      border-radius: 40px;
    }
    .icon-spacing {
      font-size: 18px; /* Ajusta o ícone junto com a fonte no mobile */
    }
  }
